#!/usr/bin/env python3
"""Fix the <rootdir> of a .gp4 generated by OpenOrbis create-gp4.exe.

create-gp4.exe hardcodes <rootdir> to its template (sce_sys/about,
sce_module, assets/{audio,fonts,images,misc,videos}) and never derives
directories from the --files list. PkgTool's BuildFSTree looks up every
file's parent directory in <rootdir> (FindDir + .First()), so any file
under a directory outside that template — e.g. LibreSprite's data/ tree —
crashes pkg_build with "Sequence contains no elements" (LibreSprite
run #13: the first data file, data/convmatr.def, has parent "data",
which is not in <rootdir>).

This script inserts the missing directories into <rootdir>, derived from
the <file targ_path> entries, preserving the ones already there.
Idempotent: running it twice changes nothing the second time.

Usage: fix-gp4-rootdir.py <pkg.gp4>
"""
import sys
import xml.etree.ElementTree as ET


def main() -> int:
    gp4_path = sys.argv[1]
    tree = ET.parse(gp4_path)
    root = tree.getroot()
    rootdir = root.find('rootdir')
    if rootdir is None:
        print(f"{gp4_path}: no <rootdir> element, nothing to fix")
        return 0

    added = []

    def ensure_dir(parent_elem, name):
        for d in parent_elem.findall('dir'):
            if d.get('targ_name') == name:
                return d
        new_dir = ET.SubElement(parent_elem, 'dir')
        new_dir.set('targ_name', name)
        added.append(name)
        return new_dir

    files = root.find('files')
    if files is not None:
        for f in files.findall('file'):
            target = f.get('targ_path') or ''
            if '/' not in target:
                continue
            parent_path = target.rsplit('/', 1)[0]
            elem = rootdir
            for part in parent_path.split('/'):
                elem = ensure_dir(elem, part)

    if added:
        print(f"{gp4_path}: added {len(added)} directorios a <rootdir>: "
              f"{', '.join(sorted(set(added)))}")
    else:
        print(f"{gp4_path}: <rootdir> ya completo, sin cambios")
    ET.indent(tree, space='\t')
    tree.write(gp4_path, encoding='utf-8', xml_declaration=True)
    return 0


if __name__ == '__main__':
    sys.exit(main())
